def _ap_Has(sub, s):
    return sub in s
def _ap_Is(b, x):
    return x == b
def classify(s, k):
    _pf_t0 = _ap_Has("a", s)
    _pf_t1 = _ap_Has(k, s)
    if _pf_t0:
        return "has a"
    elif _pf_t1:
        return f"has {k}"
    else:
        return "neither"
def truthy(x):
    _pf_t2 = _ap_Is(True, x)
    if _pf_t2:
        return "yes"
    else:
        return "no"
print(classify("cat", "z"))
print(classify("dog", "o"))
print(classify("xyz", "q"))
print(truthy(True))
print(truthy(False))
